// Every check and the endpoint it reads are declared here, in the workflow.
// The replay workflow uses the same allow-list.
const CHECKS = {
  MFA_ENABLED: '/config/mfa',
  LOGGING_ENABLED: '/config/logging',
  PASSWORD_POLICY: '/config/password_policy',
  FLAKY_DEPENDENCY: '/config/flaky',
  BROKEN_DEPENDENCY: '/config/broken',
};
return Object.entries(CHECKS).map(([check_name, path]) => ({ json: { check_name, path } }));

// Every response, including failures, becomes a verdict. PASS or FAIL only when
// the response actually answers the question; everything else is MANUAL_REVIEW,
// so a broken dependency can never be reported as compliant.
const check = $('Check list').item.json;
const status = Number($json.statusCode ?? 0);
const body = $json.body ?? {};
const transportError = $json.error ? String($json.error.message ?? $json.error) : null;

// An expected "not found" is a meaningful answer, not a system failure.
const notFound = status === 404 && body.error === 'NoSuchEntity';

let verdict = 'MANUAL_REVIEW';
let evidence;

if (transportError || status === 0 || status >= 500) {
  evidence = `SYSTEM ERROR: ${transportError ?? 'HTTP ' + status}. Not evaluated.`;
} else {
  switch (check.check_name) {
    case 'MFA_ENABLED':
    case 'LOGGING_ENABLED':
    case 'FLAKY_DEPENDENCY':
    case 'BROKEN_DEPENDENCY':
      if (status === 200 && typeof body.enabled === 'boolean') {
        verdict = body.enabled ? 'PASS' : 'FAIL';
        evidence = `enabled=${body.enabled}`;
      } else {
        evidence = `Unexpected response: HTTP ${status}`;
      }
      break;
    case 'PASSWORD_POLICY':
      if (notFound) { verdict = 'FAIL'; evidence = 'No password policy is configured.'; }
      else if (status === 200) { verdict = 'PASS'; evidence = 'Password policy present.'; }
      else evidence = `Unexpected response: HTTP ${status}`;
      break;
    default:
      evidence = `No evaluation logic for ${check.check_name}.`;
  }
}

return { json: { check_name: check.check_name, status: verdict, evidence, raw: { status_code: status || null, body } } };
